# This file extracts embedded images from PDF documents.

import hashlib
import logging
import re
from pathlib import Path

# PyMuPDF is imported under its historical name `fitz`, which is the
# API used throughout this module.
import pymupdf as fitz

logger = logging.getLogger("app.rag.image_extractor")

# Document ids are generated by this application (uuid4), so the same
# conservative pattern used by document_service is enforced before any
# path is built from an id.
DOCUMENT_ID_PATTERN = re.compile(r"^[A-Za-z0-9_-]{1,64}$")

# Only formats the downstream vision path can actually open are stored;
# exotic PDF encodings (JBIG2, JPEG2000) are skipped with a log line
# instead of failing the upload or storing an unusable asset.
SUPPORTED_IMAGE_EXTENSIONS = {
    "bmp",
    "gif",
    "jpeg",
    "jpg",
    "png",
    "tif",
    "tiff",
    "webp",
}

# How much of the page's text layer travels with the image as its
# caption / surrounding context. This is what makes image retrieval
# genuinely image-aware inside the existing 1024-dimension text
# embedding space (see embedding_service.get_embedding_text).
MAX_CAPTION_CHARS = 500


def _page_text_excerpt(page) -> str:
    """Return a whitespace-normalized excerpt of the page text layer.

    Used as the image caption/surrounding context. Scanned pages have
    no text layer, in which case the excerpt is empty and the image
    simply carries no caption.
    """

    try:
        text = page.get_text("text") or ""
    except Exception:
        logger.warning(
            "Page text could not be read for an image caption.",
            exc_info=True,
        )
        return ""

    return " ".join(text.split())[:MAX_CAPTION_CHARS]


def extract_images_from_pdf(
    document_path: Path,
    document_id: str,
    image_storage_dir: Path,
) -> list[dict]:
    # Store information about all extracted images.
    image_units = []

    if (
        not isinstance(document_id, str)
        or not DOCUMENT_ID_PATTERN.match(document_id.strip())
    ):
        raise ValueError(
            "document_id must contain only letters, numbers, "
            "hyphens, and underscores."
        )

    document_id = document_id.strip()

    # Create a directory dedicated to this document.
    document_image_dir = image_storage_dir / document_id

    # Make sure the directory exists.
    document_image_dir.mkdir(parents=True, exist_ok=True)

    # Open the PDF.
    pdf_document = fitz.open(document_path)

    # Keep track of images inside the document.
    image_counter = 0

    try:
        # Process every page.
        for page_number, page in enumerate(
            pdf_document,
            start=1,
        ):

            # Get all images embedded on this page.
            images = page.get_images(full=True)

            # Surrounding-page context is read once per page.
            caption = _page_text_excerpt(page)

            # Process every image.
            for image_index, image_info in enumerate(
                images,
                start=1,
            ):

                # Get the internal PDF image reference.
                xref = image_info[0]

                try:
                    # Extract the image bytes and extension.
                    image_data = pdf_document.extract_image(xref)
                except Exception:
                    logger.warning(
                        "Skipping unreadable image %s on page %s of "
                        "document %s.",
                        image_index,
                        page_number,
                        document_id,
                        exc_info=True,
                    )
                    continue

                # Get the actual image bytes.
                image_bytes = image_data.get("image") or b""

                # Get the image format.
                image_extension = (
                    image_data.get("ext") or ""
                ).lower()

                # Graceful handling: empty or unsupported payloads are
                # skipped instead of stored as unusable files.
                if not image_bytes:
                    logger.warning(
                        "Skipping empty image %s on page %s of "
                        "document %s.",
                        image_index,
                        page_number,
                        document_id,
                    )
                    continue

                if image_extension not in SUPPORTED_IMAGE_EXTENSIONS:
                    logger.warning(
                        "Skipping unsupported image format %r on "
                        "page %s of document %s.",
                        image_extension,
                        page_number,
                        document_id,
                    )
                    continue

                # Content hash: repeated ingestion of the same PDF
                # writes the same filename (overwrite, never
                # duplicate), and the hash travels in the metadata so
                # identical assets can be recognized across documents.
                image_hash = hashlib.sha256(image_bytes).hexdigest()

                # Generate a unique image number.
                image_counter += 1

                # Create the image filename (content-addressed).
                image_filename = (
                    f"page_{page_number}"
                    f"_img_{image_index}"
                    f"_{image_hash[:12]}"
                    f".{image_extension}"
                )

                # Build the image storage path.
                image_path = document_image_dir / image_filename

                # Defensive containment check: the built path must
                # stay inside this document's image directory.
                try:
                    resolved_image_path = image_path.resolve()
                    resolved_image_path.relative_to(
                        document_image_dir.resolve()
                    )
                except (ValueError, OSError):
                    logger.warning(
                        "Skipping image with an unsafe path on page "
                        "%s of document %s.",
                        page_number,
                        document_id,
                    )
                    continue

                # Save the image to disk (idempotent overwrite).
                image_path.write_bytes(image_bytes)

                # Create a reference that can be stored
                # in our content metadata.
                content_ref = str(
                    image_path.relative_to(
                        image_storage_dir.parent
                    )
                ).replace("\\", "/")

                # Create the image content unit.
                image_unit = {
                    "document_id": document_id,
                    "content_type": "image",
                    "page_number": page_number,
                    "image_id": (
                        f"{document_id}_"
                        f"image_{image_counter}"
                    ),
                    "content_ref": content_ref,
                    "image_format": image_extension,
                    "caption": caption,
                    "image_sha256": image_hash,
                    "source": "pdf_image",
                }

                # Add the image unit to the result.
                image_units.append(image_unit)

    finally:
        # Always close the PDF.
        pdf_document.close()

    # Return all extracted image units.
    return image_units
